import{_ as d,W as r,X as p,a1 as e}from"./framework-af1ddc77.js";const a={};function n(o,t){return r(),p("div",null,[...t[0]||(t[0]=[e('<h1 id="清华gpa" tabindex="-1"><a class="header-anchor" href="#清华gpa" aria-hidden="true">#</a> 清华GPA</h1><p>清华的课程成绩以等级制或合格制记载，并换算成绩点计算出GPA。</p><p>由于成绩记载改革，当前清华的成绩记载已经不使用百分制的分数，以下对应表格仅供参考。授课老师在分数评定过程中可能使用或可能不使用百分制分数。若使用，百分制分数与等级的对应关系由授课老师自行决定；也可能全过程不存在百分制分数直接依据课程表现评定等级。</p><table><thead><tr><th>等级</th><th>绩点</th><th>百分制范围</th><th>对应百分制数值</th></tr></thead><tbody><tr><td>A+</td><td>4.0</td><td>95-100</td><td>100</td></tr><tr><td>A</td><td>4.0</td><td>95-100</td><td>98</td></tr><tr><td>A-</td><td>4.0</td><td>90-94</td><td>92</td></tr><tr><td>B+</td><td>3.6</td><td>85-89</td><td>87</td></tr><tr><td>B</td><td>3.3</td><td>80-84</td><td>82</td></tr><tr><td>B-</td><td>3.0</td><td>77-79</td><td>78</td></tr><tr><td>C+</td><td>2.6</td><td>73-76</td><td>75</td></tr><tr><td>C</td><td>2.3</td><td>70-72</td><td>71</td></tr><tr><td>C-</td><td>2.0</td><td>67-69</td><td>68</td></tr><tr><td>D+</td><td>1.6</td><td>63-66</td><td>65</td></tr><tr><td>D</td><td>1.3</td><td>60-62</td><td>61</td></tr><tr><td>F</td><td>0</td><td>0-59</td><td>0</td></tr></tbody></table><p>表中“百分制范围”系指在老版本（2015年）成绩管理规定中给出的百分成绩到等级的映射；“对应百分制数值”系指适用于在改革过渡时期（15-18年）入学的学生等级到百分成绩的映射。均仅供参考。</p><p>GPA计算公式：GPA = (每门计入GPA的课绩点×学分的乘积之和) ÷ (计入GPA的总学分)，<strong>四舍五入保留一位小数记载</strong>。</p><p>其他不计入GPA的等级：</p><p><strong>P(pass)：通过</strong></p><p>部分课程计入学分但不计入GPA，成绩单中只记录P/F，这些课又叫pf课，通常比较抢手。</p><p>一个学期亦可以选择一门“课程属性”（培养方案中的属性）为任选的课程手动计P/F，也不计入GPA。</p><p><strong>W(withdrew)：退课</strong></p><p>在退课阶段（通常上了不到半学期）将课程退掉不上了，记录W，补退选阶段退课的（通常为开学第一周和第二周），不记录W。</p><p><strong>I(Incomplete)：未完成</strong></p><p>在课程考核期间因身心疾病等特殊情况不能参加考核环节，提出申请，经教学主管部门批准后备案记载。</p><p>在学校规定期间内完成考核后，登载考核成绩，并取消原“I”记录。</p><p><strong>Ex(exempted)：免修</strong></p><p>通过教务批准免修的课，学分计入，但是不计入GPA。</p><p>参考文献：《清华大学课程成绩管理办法》（2025年版）</p><hr><p><em>上次修改时间：2026-8-31</em><em>贡献者：自76张广昱，无52🐋</em></p>',20)])])}const h=d(a,[["render",n],["__file","thugpa.html.vue"]]);export{h as default};
